from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations, product
import heapq


def _ledger(data, sequence_first, original_tax_base):
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (sequence, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        base = raw if original_tax_base else net
        tax = rounded(base * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows_by_name = {}
    for name in names:
        rows_by_name[name] = [row for row in packages[name]
                              if row["version"] not in blocked.get(name, [])
                              and (name not in pins or row["version"] == pins[name])]

    best = None
    best_vector = None
    choices = [[None] + rows_by_name[name] for name in names]
    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment) if row is not None}
        valid = True
        for name, bounds in roots.items():
            row = selected.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in selected}
        for name, row in selected.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_row = selected.get(target)
                if (target_row is None or
                        not dep["min"] <= target_row["version"] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # The installed set must be precisely the active closure of the roots.
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            pending.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in selected):
            continue
        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best = {name: row["version"] for name, row in selected.items()}

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_ids = None
    best_value = None

    for selected in combinations(options, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        end = None
        overlap = False
        for job in ordered:
            if end is not None and job["start"] < end:
                overlap = True
                break
            end = job["end"]
        if overlap:
            continue
        selected_ids = sorted(ids)
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids > best_ids)):
            best_value, best_ids = value, selected_ids

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << index for index, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1

    def add_visit(mask, node):
        return mask | bit_for.get(node, 0)

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial = (source, add_visit(0, source), data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial[1], initial[2])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask and remaining == 0:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            next_node = edge["v"]
            next_mask = add_visit(mask, next_node)
            durations = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                durations.append((duration, remaining - 1))
            for duration, next_remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _ledger(data, True, True),
    "component_02": lambda data: _ledger(data, False, False),
    "component_03": lambda data: _ledger(data, True, False),
    "component_04": lambda data: _ledger(data, False, True),
    "component_05": lambda data: _ledger(data, True, True),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
